/**
 * API guard — enforced only when APP_PASSWORD is configured.
 * Requires the X-ATT-Token header issued by POST /api/auth/login.
 *
 * The desktop shell (and the Windows service controller) authenticates with a
 * per-boot LOCAL TOKEN instead: it is generated by the backend, written to
 * <ATT_HOME>/runtime.json and honoured ONLY for connections from this machine's
 * loopback interface, so a staff password is never needed by the app itself and
 * the token is useless to anyone off-box.
 */
const { expectedToken } = require('../routes/auth');
const { getLocalToken } = require('../services/instance');

function isLoopback(req) {
  const ip = req.ip || req.socket?.remoteAddress || '';
  return ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
}

module.exports = function attAuth(req, res, next) {
  const token = expectedToken();
  if (!token) return next(); // auth not configured → LAN-trusted mode
  if (req.headers['x-att-token'] === token) return next();

  const localToken = getLocalToken();
  if (localToken && isLoopback(req) && req.headers['x-att-local-token'] === localToken) {
    req.attLocal = true;
    return next();
  }
  return res.status(401).json({ error: 'Authentication required' });
};
